38	/**
39	 * DWARF record parser.
40	 *
41	 * We only implement enough DWARF functionality to convert from PC address
42	 * to file and line number information.
43	 *
44	 * This means (although they're not part of the public API of this class), we
45	 * can parse Debug Information Entries (DIEs), abbreviations, attributes (of
46	 * all forms), and we can interpret bytecode for the line number VM.
47	 *
48	 * We can interpret DWARF records of version 2, 3, or 4, although we don't
49	 * actually support many of the version 4 features (such as VLIW, multiple
50	 * operations per instruction)
51	 *
52	 * Note that the DWARF record parser does not allocate heap memory at all.
53	 * This is on purpose: you can use the parser from
54	 * memory-constrained situations (such as an exception handler for
55	 * std::out_of_memory)  If it weren't for this requirement, some things would
56	 * be much simpler: the Path class would be unnecessary and would be replaced
57	 * with a std::string; the list of file names in the line number VM would be
58	 * kept as a vector of strings instead of re-executing the program to look for
59	 * DW_LNE_define_file instructions, etc.
60	 */
61	class Dwarf final
62	{
63	    // Note that Dwarf uses (and returns) std::string_view a lot.
64	    // The std::string_view point within sections in the ELF file, and so will
65	    // be live for as long as the passed-in Elf is live.
66	public:
67	    /** Create a DWARF parser around an ELF file. */
68	    explicit Dwarf(const std::shared_ptr<Elf> & elf);
69	
70	    /**
71	     * More than one location info may exist if current frame is an inline
72	     * function call.
73	     */
74	    static constexpr uint32_t kMaxInlineLocationInfoPerFrame = 10;
75	
76	    /**
77	      * Represent a file path a s collection of three parts (base directory,
78	      * subdirectory, and file).
79	      */
80	    class Path
81	    {
82	    public:
83	        Path() = default;
84	
85	        Path(std::string_view baseDir, std::string_view subDir, std::string_view file);
86	
87	        std::string_view baseDir() const { return baseDir_; }
88	        std::string_view subDir() const { return subDir_; }
89	        std::string_view file() const { return file_; }
90	
91	        size_t size() const;
92	
93	        /**
94	        * Copy the Path to a buffer of size bufSize.
95	        *
96	        * toBuffer behaves like snprintf: It will always null-terminate the
97	        * buffer (so it will copy at most bufSize-1 bytes), and it will return
98	        * the number of bytes that would have been written if there had been
99	        * enough room, so, if toBuffer returns a value >= bufSize, the output
100	        * was truncated.
101	        */
102	        size_t toBuffer(char * buf, size_t bufSize) const;
103	
104	        void toString(std::string & dest) const;
105	        std::string toString() const
106	        {
107	            std::string s;
108	            toString(s);
109	            return s;
110	        }
111	
112	        // TODO(tudorb): Implement operator==, operator!=; not as easy as it
113	        // seems as the same path can be represented in multiple ways
114	    private:
115	        std::string_view baseDir_; /// NOLINT
116	        std::string_view subDir_; /// NOLINT
117	        std::string_view file_; /// NOLINT
118	    };
119	
120	    // Indicates inline function `name` is called  at `line@file`.
121	    struct CallLocation
122	    {
123	        Path file = {};
124	        uint64_t line = 0;
125	        std::string_view name;
126	    };
127	
128	    enum class LocationInfoMode
129	    {
130	        // Don't resolve location info.
131	        DISABLED,
132	        // Perform CU lookup using .debug_aranges (might be incomplete).
133	        FAST,
134	        // Scan all CU in .debug_info (slow!) on .debug_aranges lookup failure.
135	        FULL,
136	        // Scan .debug_info (super slower, use with caution) for inline functions in
137	        // addition to FULL.
138	        FULL_WITH_INLINE,
139	    };
140	
141	    struct LocationInfo
142	    {
143	        bool has_main_file = false;
144	        Path main_file;
145	
146	        bool has_file_and_line = false;
147	        Path file;
148	        uint64_t line = 0;
149	    };
150	
151	    /**
152	     * Frame information: symbol name and location.
153	     */
154	    struct SymbolizedFrame
155	    {
156	        bool found = false;
157	        uintptr_t addr = 0;
158	        // Mangled symbol name. Use `folly::demangle()` to demangle it.
159	        const char * name = nullptr;
160	        LocationInfo location;
161	        std::shared_ptr<const Elf> file;
162	
163	        void clear() { *this = SymbolizedFrame(); }
164	    };
165	
166	    /** Find the file and line number information corresponding to address.
167	      * The address must be physical - offset in object file without offset in virtual memory where the object is loaded.
168	      */
169	    bool findAddress(uintptr_t address, LocationInfo & info, LocationInfoMode mode, std::vector<SymbolizedFrame> & inline_frames) const;
170	
171	private:
172	    static bool findDebugInfoOffset(uintptr_t address, std::string_view aranges, uint64_t & offset);
173	
174	    void init();
175	
176	    std::shared_ptr<const Elf> elf_; /// NOLINT
177	
178	    // DWARF section made up of chunks, each prefixed with a length header.
179	    // The length indicates whether the chunk is DWARF-32 or DWARF-64, which
180	    // guides interpretation of "section offset" records.
181	    // (yes, DWARF-32 and DWARF-64 sections may coexist in the same file)
182	    class Section
183	    {
184	    public:
185	        Section() : is64_bit(false) {}
186	
187	        explicit Section(std::string_view d);
188	
189	        // Return next chunk, if any; the 4- or 12-byte length was already
190	        // parsed and isn't part of the chunk.
191	        bool next(std::string_view & chunk);
192	
193	        // Is the current chunk 64 bit?
194	        bool is64Bit() const { return is64_bit; }
195	
196	    private:
197	        // Yes, 32- and 64- bit sections may coexist.  Yikes!
198	        bool is64_bit;
199	        std::string_view data;
200	    };
201	
202	    // Abbreviation for a Debugging Information Entry.
203	    struct DIEAbbreviation
204	    {
205	        uint64_t code = 0;
206	        uint64_t tag = 0;
207	        bool has_children = false;
208	
209	        std::string_view attributes;
210	    };
211	
212	    // Debugging information entry to define a low-level representation of a
213	    // source program. Each debugging information entry consists of an identifying
214	    // tag and a series of attributes. An entry, or group of entries together,
215	    // provide a description of a corresponding entity in the source program.
216	    struct Die
217	    {
218	        bool is64Bit; /// NOLINT
219	        // Offset from start to first attribute
220	        uint8_t attr_offset;
221	        // Offset within debug info.
222	        uint32_t offset;
223	        uint64_t code;
224	        DIEAbbreviation abbr;
225	    };
226	
227	    struct AttributeSpec
228	    {
229	        uint64_t name = 0;
230	        uint64_t form = 0;
231	
232	        explicit operator bool() const { return name != 0 || form != 0; }
233	    };
234	
235	    struct Attribute
236	    {
237	        AttributeSpec spec;
238	        const Die & die;
239	        std::variant<uint64_t, std::string_view> attr_value;
240	    };
241	
242	    struct CompilationUnit
243	    {
244	        bool is64Bit; /// NOLINT
245	        uint8_t version;
246	        uint8_t addr_size;
247	        // Offset in .debug_info of this compilation unit.
248	        uint32_t offset;
249	        uint32_t size;
250	        // Offset in .debug_info for the first DIE in this compilation unit.
251	        uint32_t first_die;
252	        uint64_t abbrev_offset;
253	        // Only the CompilationUnit that contains the caller functions needs this cache.
254	        // Indexed by (abbr.code - 1) if (abbr.code - 1) < abbrCache.size();
255	        std::vector<DIEAbbreviation> abbr_cache;
256	    };
257	
258	    static CompilationUnit getCompilationUnit(std::string_view info, uint64_t offset);
259	
260	    /** cu must exist during the life cycle of created detail::Die. */
261	    Die getDieAtOffset(const CompilationUnit & cu, uint64_t offset) const;
262	
263	    bool findLocation(
264	        uintptr_t address,
265	        LocationInfoMode mode,
266	        CompilationUnit & cu,
267	        LocationInfo & info,
268	        std::vector<SymbolizedFrame> & inline_frames) const;
269	
270	    /**
271	     * Finds a subprogram debugging info entry that contains a given address among
272	     * children of given die. Depth first search.
273	     */
274	    void findSubProgramDieForAddress(
275	        const CompilationUnit & cu, const Die & die, uint64_t address, std::optional<uint64_t> base_addr_cu, Die & subprogram) const;
276	
277	    // Interpreter for the line number bytecode VM
278	    class LineNumberVM
279	    {
280	    public:
281	        LineNumberVM(std::string_view data, std::string_view compilationDirectory);
282	
283	        bool findAddress(uintptr_t target, Path & file, uint64_t & line);
284	
285	        /** Gets full file name at given index including directory. */
286	        Path getFullFileName(uint64_t index) const
287	        {
288	            auto fn = getFileName(index);
289	            return Path({}, getIncludeDirectory(fn.directoryIndex), fn.relativeName);
290	        }
291	
292	    private:
293	        void init();
294	        void reset();
295	
296	        // Execute until we commit one new row to the line number matrix
297	        bool next(std::string_view & program);
298	        enum StepResult
299	        {
300	            CONTINUE, // Continue feeding opcodes
301	            COMMIT, // Commit new <address, file, line> tuple
302	            END, // End of sequence
303	        };
304	        // Execute one opcode
305	        StepResult step(std::string_view & program);
306	
307	        struct FileName
308	        {
309	            std::string_view relativeName; /// NOLINT
310	            // 0 = current compilation directory
311	            // otherwise, 1-based index in the list of include directories
312	            uint64_t directoryIndex; /// NOLINT
313	        };
314	        // Read one FileName object, remove_prefix program
315	        static bool readFileName(std::string_view & program, FileName & fn);
316	
317	        // Get file name at given index; may be in the initial table
318	        // (fileNames_) or defined using DW_LNE_define_file (and we reexecute
319	        // enough of the program to find it, if so)
320	        FileName getFileName(uint64_t index) const;
321	
322	        // Get include directory at given index
323	        std::string_view getIncludeDirectory(uint64_t index) const;
324	
325	        // Execute opcodes until finding a DW_LNE_define_file and return true;
326	        // return file at the end.
327	        bool nextDefineFile(std::string_view & program, FileName & fn) const;
328	
329	        // Initialization
330	        bool is64Bit_; /// NOLINT
331	        std::string_view data_; /// NOLINT
332	        std::string_view compilationDirectory_; /// NOLINT
333	
334	        // Header
335	        uint16_t version_; /// NOLINT
336	        uint8_t minLength_; /// NOLINT
337	        bool defaultIsStmt_; /// NOLINT
338	        int8_t lineBase_; /// NOLINT
339	        uint8_t lineRange_; /// NOLINT
340	        uint8_t opcodeBase_; /// NOLINT
341	        const uint8_t * standardOpcodeLengths_; /// NOLINT
342	
343	        std::string_view includeDirectories_; /// NOLINT
344	        size_t includeDirectoryCount_; /// NOLINT
345	
346	        std::string_view fileNames_; /// NOLINT
347	        size_t fileNameCount_; /// NOLINT
348	
349	        // State machine registers
350	        uint64_t address_; /// NOLINT
351	        uint64_t file_; /// NOLINT
352	        uint64_t line_; /// NOLINT
353	        uint64_t column_; /// NOLINT
354	        bool isStmt_; /// NOLINT
355	        bool basicBlock_; /// NOLINT
356	        bool endSequence_; /// NOLINT
357	        bool prologueEnd_; /// NOLINT
358	        bool epilogueBegin_; /// NOLINT
359	        uint64_t isa_; /// NOLINT
360	        uint64_t discriminator_; /// NOLINT
361	    };
362	
363	    /**
364	     * Finds inlined subroutine DIEs and their caller lines that contains a given
365	     * address among children of given die. Depth first search.
366	     */
367	    void findInlinedSubroutineDieForAddress(
368	        const CompilationUnit & cu,
369	        const Die & die,
370	        const LineNumberVM & line_vm,
371	        uint64_t address,
372	        std::optional<uint64_t> base_addr_cu,
373	        std::vector<CallLocation> & locations,
374	        size_t max_size) const;
375	
376	    // Read an abbreviation from a std::string_view, return true if at end; remove_prefix section
377	    static bool readAbbreviation(std::string_view & section, DIEAbbreviation & abbr);
378	
379	    static void readCompilationUnitAbbrs(std::string_view abbrev, CompilationUnit & cu);
380	
381	    /**
382	     * Iterates over all children of a debugging info entry, calling the given
383	     * callable for each. Iteration is stopped early if any of the calls return
384	     * false. Returns the offset of next DIE after iterations.
385	     */
386	    size_t forEachChild(const CompilationUnit & cu, const Die & die, std::function<bool(const Die & die)> f) const;
387	
388	    // Get abbreviation corresponding to a code, in the chunk starting at
389	    // offset in the .debug_abbrev section
390	    DIEAbbreviation getAbbreviation(uint64_t code, uint64_t offset) const;
391	
392	    /**
393	     * Iterates over all attributes of a debugging info entry, calling the given
394	     * callable for each. If all attributes are visited, then return the offset of
395	     * next DIE, or else iteration is stopped early and return size_t(-1) if any
396	     * of the calls return false.
397	     */
398	    size_t forEachAttribute(const CompilationUnit & cu, const Die & die, std::function<bool(const Attribute & die)> f) const;
399	
400	    Attribute readAttribute(const Die & die, AttributeSpec spec, std::string_view & info) const;
401	
402	    // Read one attribute <name, form> pair, remove_prefix sp; returns <0, 0> at end.
403	    static AttributeSpec readAttributeSpec(std::string_view & sp);
404	
405	    // Read one attribute value, remove_prefix sp
406	    using AttributeValue = std::variant<uint64_t, std::string_view>;
407	    AttributeValue readAttributeValue(std::string_view & sp, uint64_t form, bool is64Bit) const;
408	
409	    // Get an ELF section by name, return true if found
410	    bool getSection(const char * name, std::string_view * section) const;
411	
412	    // Get a string from the .debug_str section
413	    std::string_view getStringFromStringSection(uint64_t offset) const;
414	
415	    template <class T>
416	    std::optional<T> getAttribute(const CompilationUnit & cu, const Die & die, uint64_t attr_name) const
417	    {
418	        std::optional<T> result;
419	        forEachAttribute(cu, die, [&](const Attribute & attr)
420	        {
421	            if (attr.spec.name == attr_name)
422	            {
423	                result = std::get<T>(attr.attr_value);
424	                return false;
425	            }
426	            return true;
427	        });
428	        return result;
429	    }
430	
431	    // Check if the given address is in the range list at the given offset in .debug_ranges.
432	    bool isAddrInRangeList(uint64_t address, std::optional<uint64_t> base_addr, size_t offset, uint8_t addr_size) const;
433	
434	    // Finds the Compilation Unit starting at offset.
435	    static CompilationUnit findCompilationUnit(std::string_view info, uint64_t targetOffset);
436	
437	    std::string_view info_; // .debug_info /// NOLINT
438	    std::string_view abbrev_; // .debug_abbrev /// NOLINT
439	    std::string_view aranges_; // .debug_aranges /// NOLINT
440	    std::string_view line_; // .debug_line /// NOLINT
441	    std::string_view strings_; // .debug_str /// NOLINT
442	    std::string_view ranges_; // .debug_ranges /// NOLINT
443	};
